'use strict';

const $ = (selector, root = document) => root.querySelector(selector);
const $$ = (selector, root = document) => [...root.querySelectorAll(selector)];
const main = $('#main');
const state = {view: 'overview', samples: [], remote: [], connection: null, capabilities: null, wizardStep: 1, template: 'launch', report: null, sent: 0, pollTimer: null, polling: false, connecting: false};
const terminal = new Set(['completed', 'failed', 'cancelled', 'interrupted']);
const templates = {
  launch: {name: 'Product launch', icon: '↗', description: 'Explore the first reactions to your next big thing.', tag: 'MESSAGING · AUDIENCE RESPONSE', title: 'Introducing a refillable coffee subscription', question: 'How might existing customers and new visitors respond to a refillable coffee subscription launch?', audience: 'Existing coffee subscribers, occasional buyers, and people trying to reduce packaging waste.', context: 'A fictional specialty coffee company is introducing reusable containers for a monthly subscription. Refills cost the same as the current plan. Containers require a refundable deposit. Assume local pickup is available and delivery has not yet been tested.', sections: [{title: 'The question behind the question', text: 'Can the offer make the refill process feel as simple as the sustainability benefit? In this fictional example, convenience and the deposit policy are the most useful things to test.'}, {title: 'Three response patterns to explore', items: ['Enthusiasts: the reusable packaging is an appealing reason to try the product, provided the return process is easy.', 'Pragmatists: the offer needs a clear explanation of the deposit, collection schedule, and what happens if a container is lost.', 'Sceptics: an environmental claim will invite questions about washing, transport, and evidence. Avoid promising an unverified benefit.']}, {title: 'A stronger next experiment', items: ['Compare a convenience-led message with a waste-reduction message in a small, real customer study.', 'Show the deposit and return journey before asking people to sign up.', 'Record the assumptions behind each scenario and revise them with actual feedback.']}], sentiment: [54, 28, 18]},
  pricing: {name: 'Price change', icon: '⌁', description: 'Rehearse the conversation before changing your price.', tag: 'PRICING · CUSTOMER TRUST', title: 'A new price for a monthly membership', question: 'How could members react to a 10% price increase if we explain the additional service being added?', audience: 'Long-term members, new members, price-sensitive customers, and customer support staff.', context: 'A fictional studio plans a 10% membership increase next quarter. It will add one additional weekly session and publish schedules further ahead. Existing members receive 30 days of notice. These are illustrative assumptions, not real customer research.', sections: [{title: 'The question behind the question', text: 'A price change also changes the promise customers think you are making. This fictional example explores whether the extra service feels relevant and whether the notice period feels fair.'}, {title: 'Three response patterns to explore', items: ['Value-focused members may accept the change when the added session is at a time they can use.', 'Price-sensitive members may need a lower-frequency option or a clear way to pause their membership.', 'Loyal members may care most about recognition, advance notice, and a chance to ask questions.']}, {title: 'A stronger next experiment', items: ['Ask a small group of actual members to explain the offer back in their own words.', 'Compare the full plan with a lower-frequency option before finalising the price.', 'Track retention and support questions after launch; update the scenario with observed evidence.']}], sentiment: [36, 31, 33]},
  crisis: {name: 'Crisis response', icon: '♧', description: 'Find the blind spots in a difficult announcement.', tag: 'REPUTATION · RESPONSE PLANNING', title: 'Responding to a service interruption', question: 'How might customers respond to our first announcement after a widespread service interruption?', audience: 'Customers affected by the interruption, unaffected customers, support staff, and industry commentators.', context: 'A fictional online service has experienced a three-hour interruption. The cause is still being investigated. The proposed response states what is known, gives the next update time, and explains how affected users can seek help. Do not invent a cause or a compensation policy.', sections: [{title: 'The question behind the question', text: 'In an uncertain situation, a response is most useful when it reduces uncertainty without inventing certainty. This fictional example rehearses the first announcement, not a real incident.'}, {title: 'Three response patterns to explore', items: ['Affected customers need a direct acknowledgement of the impact and a useful next step.', 'Support staff need wording that is consistent with what the investigation actually knows.', 'Commentators may question vague claims or an update schedule that the team cannot meet.']}, {title: 'A stronger next experiment', items: ['Have support staff identify the questions the announcement leaves unanswered.', 'Review the wording against the incident facts before publication.', 'Set a specific next update time and assign a person responsible for keeping it.']}], sentiment: [27, 41, 32]}
};

function el(tag, className, text) {const node = document.createElement(tag); if (className) node.className = className; if (text !== undefined) node.textContent = text; return node;}
function toast(message) {const box = $('#toast'); box.textContent = message; box.hidden = false; clearTimeout(toast.timer); toast.timer = setTimeout(() => {box.hidden = true;}, 5500);}
function setView(view) {if (!['overview','scenarios','privacy','plans','settings','account'].includes(view)) view = 'overview'; state.view = view; if (location.hash !== '#' + view) location.hash = view; else render();}
function heading(eyebrow, title, subtitle, action = true) {const wrap = el('div','welcome-row'); const left = el('div'); left.append(el('p','page-eyebrow',eyebrow),el('h1','page-title',title)); if(subtitle) left.append(el('p','muted',subtitle)); wrap.append(left); if(action){const b=el('button','button button-dark','New scenario');b.dataset.action='new';b.append(el('span','','+'));wrap.append(b);}return wrap;}
function graphMarkup() {return '<div class="graph-grid"></div><span class="graph-float">ONE DECISION. MANY PERSPECTIVES.</span><svg class="graph-svg" viewBox="0 0 400 285" role="img" aria-label="Illustration of connected audience perspectives, not simulation data"><g class="graph-lines"><path d="M197 140 130 95 69 126 112 187 197 140 249 70 306 98 197 140 311 184 249 219 197 140 130 95 150 39 249 70 338 41 306 98 365 144 311 184 346 250 249 219 201 264 112 187 60 224 69 126 26 71 130 95 249 70 311 184 112 187 249 219 69 126 306 98 249 219 150 39 197 140 365 144 249 70" fill="none"/><path d="M35 167 69 126M130 95 94 48M197 140 219 28M306 98 376 76M112 187 151 247M249 219 302 258M311 184 383 210M26 71 94 48M35 167 60 224M219 28 338 41M150 39 219 28" fill="none"/></g><g class="graph-nodes"><circle cx="197" cy="140" r="10" class="core"/><circle cx="130" cy="95" r="6" class="lime"/><circle cx="69" cy="126" r="4"/><circle cx="112" cy="187" r="6"/><circle cx="249" cy="70" r="7" class="lime"/><circle cx="306" cy="98" r="5"/><circle cx="311" cy="184" r="6" class="lime"/><circle cx="249" cy="219" r="4"/><circle cx="150" cy="39" r="3"/><circle cx="338" cy="41" r="3"/><circle cx="365" cy="144" r="4"/><circle cx="346" cy="250" r="3"/><circle cx="201" cy="264" r="3"/><circle cx="60" cy="224" r="4"/><circle cx="26" cy="71" r="3"/><circle cx="35" cy="167" r="2.5"/><circle cx="94" cy="48" r="2.5"/><circle cx="219" cy="28" r="2.5"/><circle cx="376" cy="76" r="2.5"/><circle cx="151" cy="247" r="3"/><circle cx="302" cy="258" r="2.5"/><circle cx="383" cy="210" r="2.5"/></g></svg><span class="graph-label label-a">What will customers ask?</span><span class="graph-label label-b">Where could this lead?</span><span class="graph-label label-c">What are we missing?</span><div class="graph-key"><span><i></i> Your decision</span><span><i></i> Different perspectives</span></div>';}
function render() {const labels = {overview:'Overview',scenarios:'My scenarios',privacy:'Privacy centre',plans:'Plans & usage',settings:'Settings',account:'Account'};$('#breadcrumb-label').textContent=labels[state.view];$$('[data-view]').forEach(a=>{a.classList.toggle('active',a.dataset.view===state.view);if(a.dataset.view===state.view)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('#scenario-count').textContent=String(state.samples.length+state.remote.length);const badge=$('#connection-status');badge.classList.toggle('connected',!!state.connection);badge.replaceChildren(el('span'),document.createTextNode(state.connection?'Connected · private gateway':'Demo · engine not connected'));main.replaceChildren();const view=el('div','view');main.append(view);({overview:renderOverview,scenarios:renderScenarios,privacy:renderPrivacy,plans:renderPlans,settings:renderSettings,account:renderAccount}[state.view])(view);}
function renderOverview(view) {view.append(heading('YOUR DECISION STUDIO','A little foresight goes a long way.','Explore the possibilities before you make your move.'));const hero=el('section','hero-card');hero.innerHTML='<div class="hero-copy"><p class="eyebrow">MAKE ROOM FOR WHAT IF</p><h2>Rehearse your<br>next move.</h2><p>Turn a question into a scenario. Explore how different audiences might respond — and what to test next.</p><button class="button button-dark" data-action="sample">Explore a sample <span>↗</span></button></div><div class="hero-visual">'+graphMarkup()+'</div>';view.append(hero);const metrics=el('div','metrics-row');[['Starter templates','03','A useful place to begin','⌘'],['Your workspace',state.connection?'Connected':'Local demo',state.connection?'Private gateway session':'No account needed to explore','◫'],['Briefs sent this session',String(state.sent).padStart(2,'0'),'Only after your explicit review','↗'],['Source available','Open','Built on the MiroFish engine','↳']].forEach(([label,value,sub,icon])=>{const m=el('div','metric'),top=el('div','metric-top');top.append(el('span','',label),el('span','',icon));m.append(top,el('strong','',value),el('small','',sub));metrics.append(m);});view.append(metrics);const sh=el('div','section-heading');sh.innerHTML='<div><h2>Start with a question.</h2><p>Three starting points. Plenty of possibilities.</p></div><button class="text-button" data-action="new">Create your own ↗</button>';view.append(sh,templateGrid());const bottom=el('div','bottom-grid'),recent=el('section','recent-panel');recent.innerHTML='<div class="section-heading"><h2>Your recent scenarios</h2><a class="text-button" href="#scenarios">View all ↗</a></div>';const all=[...state.remote,...state.samples];if(all.length)recent.append(runCard(all[0],true));else recent.innerHTML+='<div class="recent-empty"><span class="empty-icon">⌘</span><div><strong>Good decisions start somewhere.</strong><p>Your first scenario will appear here.</p></div></div>';const privacy=el('section','privacy-callout');privacy.innerHTML='<span class="shield">♧</span><div><h3>Your brief. Your boundaries.</h3><p>Explore locally, redact identifying details, and review where your data goes before a cloud run.</p><a href="#privacy">Explore the privacy centre ↗</a></div>';bottom.append(recent,privacy);view.append(bottom);const note=el('p','small muted','Sample reports are prewritten illustrations. Real simulations are synthetic scenarios, not surveys or reliable predictions.');note.style.margin='23px 0 0';note.style.fontSize='12px';view.append(note);}
function templateGrid() {const grid=el('div','template-grid');Object.entries(templates).forEach(([key,t])=>{const b=el('button','template-card');b.dataset.template=key;b.append(el('span','template-icon',t.icon),el('span','card-arrow','↗'),el('h3','',t.name),el('p','',t.description),el('small','',t.tag));grid.append(b);});return grid;}
function renderScenarios(view) {view.append(heading('FROM QUESTION TO POSSIBILITY','Your scenario library.','Drafts and sample reports stay in this tab. Connected runs are stored by your gateway.'));const bar=el('div','notice');bar.textContent=state.connection?'Connected runs appear alongside clearly labelled local samples. Real runs use your gateway’s credit allowance.':'You’re in local demo mode. Sample reports are prewritten examples; connect your private gateway to run MiroFish.';view.append(bar);const all=[...state.remote,...state.samples];if(!all.length){const empty=el('div','large-empty');empty.innerHTML='<div class="empty-icon">⌘</div><h2>Your next decision starts here.</h2><p>Try a template or build a brief of your own.</p><button class="button button-dark" data-action="new">Create a scenario <span>+</span></button>';view.append(empty);}else{const list=el('div','scenario-list');all.forEach(r=>list.append(runCard(r)));view.append(list);}const section=el('div','section-heading');section.style.marginTop='30px';section.innerHTML='<div><h2>Need a starting point?</h2><p>A template helps you ask a sharper question.</p></div>';view.append(section,templateGrid());}
function runCard(run,compact=false) {const card=el('article','run-card');card.append(el('span','empty-icon',run.local?'◇':'⌘'));const info=el('div','run-description');info.append(el('span','pill'+(run.status==='completed'?' lime':''),run.local?'ILLUSTRATIVE SAMPLE':run.status.toUpperCase()),el('h3','',run.title),el('p','',run.local?'Local preview · not an analysis of your brief':(run.stage||'Queued')+' · '+(run.credits_reserved||0)+' credits reserved'));if(!run.local&&!terminal.has(run.status)){const progress=el('progress');progress.max=100;progress.value=run.progress||0;progress.setAttribute('aria-label','Simulation progress');info.append(progress);}if(run.error)info.append(el('p','form-error',run.error));card.append(info);const actions=el('div','run-actions');if(run.local||run.result){const open=el('button','button button-quiet','View report ↗');open.dataset.report=run.id;actions.append(open);}else if(!terminal.has(run.status)){const refresh=el('button','button button-quiet','Refresh');refresh.dataset.refresh=run.id;actions.append(refresh);}if(!compact&&(run.local||terminal.has(run.status))){const del=el('button','icon-button','×');del.setAttribute('aria-label','Delete '+run.title);del.dataset.delete=run.id;actions.append(del);}card.append(actions);return card;}
function renderPrivacy(view) {view.append(heading('DESIGNED FOR DELIBERATE SHARING','Your brief. Your boundaries.','Privacy starts with knowing what stays here — and what leaves.',false));const split=el('div','split-content'),left=el('section','content-card');left.innerHTML='<h2>Less exposure. More control.</h2><div class="privacy-feature"><span class="feature-icon">◌</span><div><h3>Explore without uploading</h3><p>Demo drafts and prewritten reports stay in memory in this tab. No analytics, third-party fonts, or advertising scripts are included.</p></div></div><div class="privacy-feature"><span class="feature-icon">♧</span><div><h3>Redact before sending</h3><p>Mask email addresses and phone numbers locally. Inspect the exact payload before you approve a real cloud run. Names and other identifiers need your manual review.</p></div></div><div class="privacy-feature"><span class="feature-icon">↳</span><div><h3>A receipt with your report</h3><p>See the processors involved. Connected runs use workspace isolation and gateway field encryption for briefs and reports. Engine files and backups need host-level protection.</p></div></div>';const right=el('section','content-card');right.innerHTML='<h2>The data journey, made visible.</h2><div class="flow-step"><span>1</span><div><strong>This browser</strong><p>Draft, redact, and review. Demo mode does not call the simulation engine.</p></div></div><div class="flow-step"><span>2</span><div><strong>Your connected gateway & MiroFish engine</strong><p>Only a reviewed, approved brief is sent. Your workspace key stays in this tab’s memory.</p></div></div><div class="flow-step"><span>3</span><div><strong>The configured LLM provider & Zep Cloud</strong><p>Real runs need external processing. Provider policies, logs, and backups can outlive a gateway deletion.</p></div></div><div class="setting-info">The default engine is not end-to-end encrypted inference. Deleting a gateway record does not guarantee immediate erasure from all processors. Dedicated hosting and alternative memory backends are future options.</div>';split.append(left,right);view.append(split);const redactor=el('section','content-card privacy-editor');redactor.innerHTML='<div class="section-heading"><div><h2>Try the local privacy check.</h2><p>No network request. No saved draft.</p></div><span class="pill lime">IN YOUR BROWSER</span></div><label>Paste a short example<textarea id="privacy-input" rows="3" maxlength="10000" placeholder="Ask Taylor at taylor@example.com to call +61 412 345 678."></textarea></label><div id="privacy-output" class="privacy-output" aria-live="polite">Your redacted text will appear here.</div><div class="privacy-demo-actions"><small id="privacy-match-count">Email and phone patterns only. Always review manually.</small><button class="button button-quiet" id="clear-redactor">Clear text ×</button></div>';view.append(redactor);const clear=el('section','content-card');clear.style.marginTop='21px';clear.innerHTML='<h2>A clean slate.</h2><p>Clear local sample reports, drafts, and your connected workspace key from this tab. Cloud run records are deleted individually from My scenarios.</p><button class="button button-danger" data-action="clear-local">Clear this tab’s data</button>';view.append(clear);}
function renderPlans(view) {view.append(heading('A MODEL THAT GROWS WITH YOU','Room for your next what if.','Proposed launch plans, in Australian dollars. Paid subscriptions are not active.',false));const usage=el('div','usage-strip');const copy=el('div');copy.append(el('strong','',state.connection?'Your pilot workspace':'You’re exploring Branchline'),el('p','',state.connection?String(state.capabilities.usage.credits_remaining)+' credits remaining · 1 + rounds reserved per real run':'Free samples. No payment details. No cloud inference in demo mode.'));const action=el('button','button button-outline',state.connection?'Refresh usage':'Connect a gateway ↗');action.dataset.action=state.connection?'refresh-usage':'settings';usage.append(copy,action);view.append(usage);const plans=[{name:'Explorer',price:'0',description:'A first look at a different way to think.',features:['Prewritten sample reports','Local brief builder','Browser-side redaction','No cloud simulations'],cta:'Explore a sample',action:'sample'},{name:'Solo',price:'49',description:'For one curious strategist and their next decision.',features:['30 credits / month','Private workspace concept','Scenario reports & export','Proposed plan — not for sale'],cta:'Build your first brief',action:'new'},{name:'Studio',price:'199',description:'A shared rehearsal habit for a growing team.',features:['150 credits / month','Team workflows planned','Comparable scenario reports','Proposed plan — not for sale'],cta:'Explore the workflow',action:'new',featured:true},{name:'Agency',price:'599',description:'For recurring client decisions and richer context.',features:['500 credits / month','Client separation planned','Higher capacity after validation','Proposed plan — not for sale'],cta:'Explore a client brief',action:'new'}];const grid=el('div','pricing-grid');plans.forEach(p=>{const card=el('section','price-card'+(p.featured?' featured':''));if(p.featured)card.append(el('span','recommended','THE TEAM STARTING POINT'));card.append(el('p','eyebrow',p.name.toUpperCase()));const price=el('div','price','$'+p.price);price.append(el('span','',' AUD / month'));card.append(price,el('p','price-description',p.description));const list=el('ul');p.features.forEach(f=>list.append(el('li','',f)));const button=el('button','button '+(p.featured?'button-dark':'button-outline'),p.cta);button.dataset.action=p.action;card.append(list,button);grid.append(card);});view.append(grid);const enterprise=el('section','enterprise-card');enterprise.innerHTML='<div><h2>Different boundaries? A dedicated Branchline.</h2><p>Proposed enterprise offering: dedicated engine, your infrastructure, negotiated processor terms. Priced to scope.</p></div><a class="button button-outline" href="https://github.com/2johnou-create/branchline/blob/main/docs/DEPLOYMENT.md" target="_blank" rel="noopener noreferrer">View deployment guide ↗</a>';view.append(enterprise);const notes=el('div','notice');notes.innerHTML='<strong>Credits keep the model sustainable.</strong> The pilot gateway reserves 1 + simulation rounds per run; this is a workload limit, not a measured-cost bill. Pricing and allowances need real cost benchmarks before launch. There is no checkout or automatic recurring charge in this version.';view.append(notes);}
function renderAccount(view){if(window.BranchlinePlatform)window.BranchlinePlatform.renderAccount(view);}
function renderSettings(view) {view.append(heading('YOUR TOOLS, CONNECTED','Make it your workspace.','Connect a private Branchline gateway when you’re ready to run the real engine.',false));const card=el('section','content-card settings-form');card.innerHTML='<h2>Simulation gateway</h2><p>The public interface works as a local demo until you connect a deployed gateway. LLM and Zep keys belong on your server, never in this form.</p><div class="setting-info">Use HTTPS for a hosted gateway. For local development, HTTP is accepted only on localhost or 127.0.0.1. Configure the gateway’s CORS origin for this site.</div><form id="connection-form"><label>Gateway origin<input id="gateway-origin" type="url" required placeholder="https://your-gateway.example.com" autocomplete="off" spellcheck="false"></label><label>Workspace access key<input id="gateway-token" type="password" required placeholder="Your provisioned workspace bearer token" autocomplete="off" spellcheck="false"></label><div class="settings-actions"><button type="submit" class="button button-dark" id="connect-button">Connect workspace <span>↗</span></button><button type="button" class="button button-outline" id="disconnect-button">Disconnect</button></div><p id="connection-error" class="form-error" role="alert" hidden></p><p class="settings-state" id="settings-state"></p></form>';if(state.connection)$('#gateway-origin',card).value=state.connection.base;$('#disconnect-button',card).disabled=!state.connection;$('#settings-state',card).textContent=state.connection?'Connected to '+state.capabilities.workspace.name+'. The key is held in this tab’s memory and disappears on reload.':'Not connected. Your access key is never saved in local storage, cookies, or URLs.';view.append(card);const help=el('section','content-card settings-form');help.style.marginTop='21px';help.innerHTML='<h2>A public interface. A private engine.</h2><p>Run the included gateway and MiroFish engine on a Python-capable host. Provision a workspace key, configure provider credentials server-side, and keep the engine’s own port off the public internet.</p><a class="button button-outline" href="https://github.com/2johnou-create/branchline/blob/main/docs/DEPLOYMENT.md" target="_blank" rel="noopener noreferrer">Open setup instructions ↗</a><h3>What is available in this version?</h3><p>Local samples, brief building, redaction, report export, and a real gateway API adapter. Self-serve accounts, payment collection, recurring billing, and enterprise hosting are launch work described in the business plan.</p>';view.append(help);}

function openWizard(template='launch') {state.template=templates[template]?template:'launch';state.wizardStep=1;const t=templates[state.template];$('#brief-title').value=t.title;$('#brief-question').value=t.question;$('#brief-audience').value=t.audience;$('#brief-context').value=t.context;$('#brief-rounds').value='5';$('#redact-toggle').checked=true;$('#processing-consent').checked=false;$('#wizard-error').hidden=true;updateWizard();$('#scenario-dialog').showModal();$('#scenario-dialog').scrollTop=0;}
function updateWizard() {const review=state.wizardStep===2;$('#wizard-step-one').hidden=review;$('#wizard-step-two').hidden=!review;$('#scenario-heading').textContent=review?'Review your boundaries.':'Set the scene.';$('#step-one-label').classList.toggle('current',!review);$('#step-two-label').classList.toggle('current',review);$('#wizard-back').textContent=review?'← Edit brief':'Cancel';$('#wizard-next').replaceChildren(document.createTextNode(review?(state.connection?'Start real simulation':'Preview sample report'):'Review brief'),el('span','','→'));$('#wizard-footnote').textContent=review?(state.connection?'Credits: '+(1+Number($('#brief-rounds').value)):'Prewritten sample · no cloud run'):'Your draft stays in this tab';$('#review-mode-label').textContent=state.connection?'CONNECTED GATEWAY':'LOCAL DEMO — NOT SENT';$('#consent-wrap').hidden=!state.connection;$('#review-disclaimer').textContent=state.connection?'Real runs process your reviewed brief through the gateway, MiroFish, the configured LLM provider, and Zep Cloud. Gateway deletion cannot guarantee immediate provider erasure.':'This opens a prewritten illustrative report. It does not analyse your brief or run MiroFish.';const path=$('#review-data-path');path.replaceChildren();(state.connection?['This browser','Your gateway','MiroFish','LLM + Zep Cloud']:['This browser only','Prewritten sample report']).forEach((label,i)=>{if(i)path.append(document.createTextNode('→'));path.append(el('span','',label));});if(review)updatePayload();}
function scrub(text) {let matches=0;let result=text.replace(/[A-Z0-9.!#$%&'*+/=?^_`{|}~-]+@[A-Z0-9](?:[A-Z0-9-]*[A-Z0-9])?(?:\.[A-Z0-9](?:[A-Z0-9-]*[A-Z0-9])?)+/gi,()=>{matches++;return '[EMAIL REMOVED]';});result=result.replace(/(?:\+?\d[\d ().-]{6,}\d)/g,(match)=>{const n=match.replace(/\D/g,'').length;if(n<8||n>15)return match;matches++;return '[PHONE REMOVED]';});return {text:result,matches};}
function getPayload() {const payload={title:$('#brief-title').value.trim(),question:$('#brief-question').value.trim(),context:$('#brief-context').value.trim(),audience:$('#brief-audience').value.trim(),rounds:Number($('#brief-rounds').value),consent_external_processing:!!state.connection&&$('#processing-consent').checked,template:state.template};let count=0;['title','question','context','audience'].forEach(key=>{const result=scrub(payload[key]);count+=result.matches;if($('#redact-toggle').checked)payload[key]=result.text;});return {payload,count};}
function updatePayload() {const {payload,count}=getPayload();$('#payload-preview').textContent=JSON.stringify(payload,null,2);$('#redaction-count').textContent=count+' '+(count===1?'pattern':'patterns')+($('#redact-toggle').checked?' masked':' found');}
async function submitWizard(event) {event.preventDefault();const error=$('#wizard-error');error.hidden=true;if(state.wizardStep===1){if(!$('#scenario-form').reportValidity())return;state.wizardStep=2;updateWizard();$('#scenario-heading').focus();return;}const {payload}=getPayload();if(!state.connection){const run={id:'local-'+crypto.randomUUID(),title:payload.title,question:payload.question,audience:payload.audience,rounds:payload.rounds,template:state.template,local:true,status:'completed',created_at:new Date().toISOString(),reviewed_payload:payload};state.samples.unshift(run);$('#scenario-dialog').close();setView('scenarios');openReport(run);toast('Sample report opened. No brief was sent or analysed.');return;}if(!$('#processing-consent').checked){error.textContent='Please review the data destinations and confirm consent before starting.';error.hidden=false;return;}const connection=state.connection;const next=$('#wizard-next');if(next.disabled)return;next.disabled=true;next.textContent='Starting…';try{const run=await api('/api/v1/runs',{method:'POST',body:JSON.stringify(payload)});if(state.connection!==connection)return;if(!run||typeof run.id!=='string')throw new Error('The gateway returned an invalid run response.');state.sent++;state.remote.unshift(run);$('#scenario-dialog').close();setView('scenarios');toast('Real simulation queued. Progress will update here.');schedulePoll();refreshCapabilities().catch(()=>{});}catch(err){if(state.connection===connection){error.textContent=err.message;error.hidden=false;}}finally{next.disabled=false;updateWizard();}}

async function api(path,options={}) {if(!state.connection)throw new Error('Connect a workspace gateway first.');const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),20000);try{const response=await fetch(state.connection.base+path,{...options,headers:{'Accept':'application/json','Authorization':'Bearer '+state.connection.token,...(options.body?{'Content-Type':'application/json'}:{}),...options.headers},signal:controller.signal,credentials:'omit',cache:'no-store',referrerPolicy:'no-referrer'});let data;try{data=await response.json();}catch{throw new Error('The gateway did not return JSON. Check the gateway origin.');}if(!response.ok){let msg=typeof data.detail==='string'?data.detail:typeof data.error==='string'?data.error:'Gateway request failed ('+response.status+').';if(response.status===401)msg='The workspace access key was not accepted. Reconnect in settings.';throw new Error(msg);}return data;}catch(err){if(err.name==='AbortError')throw new Error('The gateway did not respond in time. Your run may still exist; refresh before retrying.');if(err instanceof TypeError)throw new Error('Could not reach the gateway. Check HTTPS, the origin, and the server’s CORS configuration.');throw err;}finally{clearTimeout(timeout);}}
function validateOrigin(value) {let url;try{url=new URL(value);}catch{throw new Error('Enter a valid gateway origin, such as https://gateway.example.com.');}const loopback=['localhost','127.0.0.1','[::1]'].includes(url.hostname);if(url.protocol!=='https:'&&!(loopback&&url.protocol==='http:'))throw new Error('Use HTTPS, or HTTP on localhost for local development.');if(url.username||url.password||url.search||url.hash||url.pathname!=='/')throw new Error('Enter the origin only, without credentials, path, query, or fragment.');return url.origin;}
async function connect(event) {
  event.preventDefault();
  if(state.connecting)return;
  const button=$('#connect-button'),error=$('#connection-error');
  const prior=state.connection,priorCapabilities=state.capabilities,priorRemote=state.remote;
  let attempt=null;
  error.hidden=true;state.connecting=true;button.disabled=true;button.textContent='Connecting…';
  try {
    const base=validateOrigin($('#gateway-origin').value.trim()),token=$('#gateway-token').value.trim();
    if(!token)throw new Error('Enter your provisioned workspace access key.');
    attempt={base,token};state.connection=attempt;
    const data=await api('/api/v1/capabilities');
    if(state.connection!==attempt)return;
    if(!data.workspace||!data.usage)throw new Error('This origin is not a compatible Branchline gateway.');
    state.capabilities=data;
    const input=$('#gateway-token');if(input)input.value='';
    await loadRuns();
    if(state.connection!==attempt)return;
    if(state.report&&!state.report.local){state.report=null;$('#report-content').replaceChildren();if($('#report-dialog').open)$('#report-dialog').close();}
    render();schedulePoll();toast('Workspace connected. Real runs are now available.');
  } catch(err) {
    if(attempt&&state.connection!==attempt)return;
    state.connection=prior;state.capabilities=priorCapabilities;state.remote=priorRemote;
    error.textContent=err.message;error.hidden=false;
  } finally {
    state.connecting=false;
    if(button.isConnected){button.disabled=false;button.textContent='Connect workspace ↗';}
  }
}
async function refreshCapabilities(){const connection=state.connection;const data=await api('/api/v1/capabilities');if(state.connection===connection)state.capabilities=data;return data;}
async function loadRuns(){const connection=state.connection;const data=await api('/api/v1/runs');if(!Array.isArray(data.runs))throw new Error('The gateway returned an invalid scenario list.');if(state.connection===connection)state.remote=data.runs;}
function schedulePoll(){clearTimeout(state.pollTimer);if(state.connection&&state.remote.some(r=>!terminal.has(r.status)))state.pollTimer=setTimeout(pollRuns,5000);}
async function pollRuns(){if(!state.connection||state.polling)return;state.polling=true;try{await loadRuns();if(['overview','scenarios'].includes(state.view))render();}catch(err){toast(err.message);}finally{state.polling=false;schedulePoll();}}
async function refreshRun(id){const connection=state.connection;try{const run=await api('/api/v1/runs/'+encodeURIComponent(id));if(state.connection!==connection)return;const i=state.remote.findIndex(r=>r.id===id);if(i>=0)state.remote[i]=run;render();schedulePoll();if(run.result)toast('Report ready. Open it from this scenario.');}catch(err){if(state.connection===connection)toast(err.message);}}
function disconnect(){clearTimeout(state.pollTimer);state.connection=null;state.capabilities=null;state.remote=[];if(state.report&&!state.report.local){state.report=null;$('#report-content').replaceChildren();if($('#report-dialog').open)$('#report-dialog').close();}render();toast('Workspace disconnected. Access key cleared from memory.');}
async function deleteRun(id){const sample=state.samples.find(r=>r.id===id);if(sample){state.samples=state.samples.filter(r=>r.id!==id);render();toast('Local sample report cleared.');return;}if(!confirm('Delete this gateway run? Upstream cleanup is best effort and provider copies may remain.'))return;const connection=state.connection;try{const receipt=await api('/api/v1/runs/'+encodeURIComponent(id),{method:'DELETE'});if(state.connection!==connection)return;state.remote=state.remote.filter(r=>r.id!==id);render();state.report={id:'receipt',title:'Deletion receipt',local:false,result:{markdown:JSON.stringify(receipt,null,2)}};openReport(state.report);toast('Gateway record deleted. Review the cleanup receipt.');}catch(err){toast(err.message);}}

function openReport(run){state.report=run;const content=$('#report-content');content.replaceChildren();$('#report-mode').textContent=run.local?'ILLUSTRATIVE SAMPLE':'GATEWAY REPORT';$('#report-mode').className='pill'+(run.local?'':' lime');content.append(el('p','eyebrow',run.local?'A REHEARSAL OF THE POSSIBILITIES':'YOUR CONNECTED WORKSPACE'),el('h2','report-heading',run.title));$('#report-heading')?.removeAttribute('id');$('.report-heading',content).id='report-heading';content.append(el('p','report-subtitle',run.local?'Prewritten reference case · Not generated from your brief':'Run '+run.id+' · '+(run.rounds||0)+' rounds'));if(run.local){const t=templates[run.template]||templates.launch;content.append(el('div','report-note','This is a prewritten, fictional example for “'+t.name+'”. It does not analyse your question, predict an outcome, or represent surveyed people. Your reviewed brief is shown separately below.'));t.sections.forEach(section=>{const sec=el('section','report-section');sec.append(el('h3','',section.title));if(section.text)sec.append(el('p','',section.text));if(section.items){const list=el('ul');section.items.forEach(text=>list.append(el('li','',text)));sec.append(list);}content.append(sec);});const chart=el('section','report-section');chart.append(el('h3','','Illustrative response mix'),el('p','','Example visualisation only. These proportions are invented to demonstrate the report format.'));const bars=el('div','sentiment-chart');['positive','neutral','negative'].forEach((name,i)=>{const span=el('span',name);span.style.width=t.sentiment[i]+'%';bars.append(span);});bars.setAttribute('role','img');bars.setAttribute('aria-label','Invented sample response mix: '+t.sentiment[0]+' percent positive, '+t.sentiment[1]+' percent neutral, '+t.sentiment[2]+' percent concerned.');chart.append(bars);const legend=el('div','chart-legend');['Positive','Neutral','Concerned'].forEach((name,i)=>{const span=el('span');span.append(el('i'),document.createTextNode(name+' '+t.sentiment[i]+'%'));legend.append(span);});chart.append(legend);content.append(chart);if(run.reviewed_payload){const brief=el('section','report-section');brief.append(el('h3','','Your reviewed brief · held locally'),el('pre','report-raw',JSON.stringify(run.reviewed_payload,null,2)));content.append(brief);}}else{content.append(el('div','report-note','This report comes from your connected gateway. Treat synthetic responses as hypotheses to test with real people and evidence.'));const text=run.result?.markdown||run.error||'No report is available for this run yet.';content.append(el('div','report-raw',text));}const receipt=el('section','receipt-box');receipt.append(el('h3','','PROCESSING RECEIPT'));if(run.local){receipt.append(el('p','','Location: this browser tab only. Engine calls: none. Result: prewritten fictional sample.'),el('p','','Reloading the page clears this sample. Exported files are under your control.'));}else{const processors=run.privacy_receipt?.processors||['Your gateway','MiroFish','Configured LLM provider','Zep Cloud'];receipt.append(el('p','','Processors: '+processors.map(p=>typeof p==='string'?p:JSON.stringify(p)).join(' → ')));(run.privacy_receipt?.notes||['Provider retention can outlive gateway deletion. No end-to-end encrypted inference is claimed.']).forEach(note=>receipt.append(el('p','',note)));}content.append(receipt);if(!$('#report-dialog').open)$('#report-dialog').showModal();$('#report-dialog').scrollTop=0;}
function sampleRun(template='launch'){const t=templates[template];return{id:'reference-'+template,title:t.title,template,local:true,status:'completed',created_at:new Date().toISOString()};}
function exportReport(){if(!state.report)return;const run=state.report;let text='BRANCHLINE\n'+run.title+'\n\n';if(run.local){const t=templates[run.template]||templates.launch;text+='ILLUSTRATIVE SAMPLE — PREWRITTEN, NOT GENERATED FROM YOUR BRIEF\nNot a prediction or a survey.\n\n';t.sections.forEach(s=>{text+=s.title+'\n'+(s.text||s.items.map(item=>'• '+item).join('\n'))+'\n\n';});text+='Invented response mix (demonstration only): '+t.sentiment.join(' / ')+'\n\n';if(run.reviewed_payload)text+='YOUR REVIEWED BRIEF (LOCAL)\n'+JSON.stringify(run.reviewed_payload,null,2)+'\n\n';text+='Processing: browser only. No engine call.\n';}else{text+='SYNTHETIC GATEWAY REPORT — validate with real evidence\n\n'+(run.result?.markdown||'No report available.')+'\n\nPROCESSING RECEIPT\n'+JSON.stringify(run.privacy_receipt||{},null,2);}const blob=new Blob([text],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),link=el('a');link.href=url;link.download='branchline-'+(run.local?'sample':'report')+'-'+new Date().toISOString().slice(0,10)+'.txt';document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Report exported. The downloaded file may contain your reviewed brief.');}
function clearLocal(){if(!confirm('Clear this tab’s drafts, samples, and workspace access key? Cloud records will remain.'))return;window.BranchlineExperience?.clearDraft();clearTimeout(state.pollTimer);state.samples=[];state.remote=[];state.connection=null;state.capabilities=null;state.report=null;state.sent=0;$('#scenario-form').reset();$('#payload-preview').textContent='';$('#report-content').replaceChildren();$('#brief-file').value='';render();toast('Local workspace data cleared. Cloud records were not changed.');}

document.addEventListener('click',async event=>{const target=event.target.closest('button,a');if(!target)return;if(target.dataset.template){openWizard(target.dataset.template);return;}if(target.dataset.report){const run=[...state.samples,...state.remote].find(r=>r.id===target.dataset.report);if(run)openReport(run);return;}if(target.dataset.delete){deleteRun(target.dataset.delete);return;}if(target.dataset.refresh){refreshRun(target.dataset.refresh);return;}switch(target.dataset.action){case'new':openWizard();break;case'sample':openReport(sampleRun());break;case'settings':setView('settings');break;case'close-dialog':$('#scenario-dialog').close();break;case'close-report':$('#report-dialog').close();break;case'clear-local':clearLocal();break;case'refresh-usage':try{await refreshCapabilities();render();toast('Usage refreshed.');}catch(err){toast(err.message);}break;}if(target.id==='disconnect-button')disconnect();if(target.id==='clear-redactor'){$('#privacy-input').value='';$('#privacy-output').textContent='Your redacted text will appear here.';$('#privacy-match-count').textContent='Email and phone patterns only. Always review manually.';}if(target.id==='import-brief')$('#brief-file').click();});
document.addEventListener('submit',event=>{if(event.target.id==='connection-form')connect(event);});
document.addEventListener('input',event=>{if(event.target.id==='privacy-input'){const result=scrub(event.target.value);$('#privacy-output').textContent=result.text||'Your redacted text will appear here.';$('#privacy-match-count').textContent=result.matches+' patterns masked. Review names and other identifiers manually.';}});
$('#scenario-form').addEventListener('submit',submitWizard);
$('#wizard-back').addEventListener('click',()=>{if(state.wizardStep===1)$('#scenario-dialog').close();else{state.wizardStep=1;$('#wizard-error').hidden=true;updateWizard();}});
$('#redact-toggle').addEventListener('change',updatePayload);
$('#processing-consent').addEventListener('change',updatePayload);
$('#export-report').addEventListener('click',exportReport);
$('#brief-file').addEventListener('change',async event=>{const file=event.target.files[0];if(!file)return;if(file.size>120000){toast('Use a text brief smaller than 120 KB.');event.target.value='';return;}try{const text=await file.text();if(text.length>30000){toast('The context field is limited to 30,000 characters. Please shorten the file.');return;}$('#brief-context').value=text;toast('Brief read locally. Review it before continuing.');}catch{toast('Could not read the text file.');}finally{event.target.value='';}});
window.addEventListener('hashchange',()=>{state.view=location.hash.slice(1)||'overview';if(!['overview','scenarios','privacy','plans','settings','account'].includes(state.view))state.view='overview';render();});
window.addEventListener('beforeunload',()=>{clearTimeout(state.pollTimer);state.connection=null;});
state.view=['overview','scenarios','privacy','plans','settings','account'].includes(location.hash.slice(1))?location.hash.slice(1):'overview';render();
